questionvariables.text:
/* Select a reference angle */
ref_index: rand(3);
ref_list: [30,45,60];
ref_angle: ref_list[ref_index+1];

/* Select a quadrant: 1, 2 or 3 */
quadrant: 1 + rand(3);

/* Construct the angle */
theta: if quadrant=1 then ref_angle
       else if quadrant=2 then 180-ref_angle
       else 180+ref_angle;

/* Calculate sine, cosine and tangent */
sin_theta: sin(theta*%pi/180);
cos_theta: cos(theta*%pi/180);
tan_theta: ratsimp(sin_theta/cos_theta);
